tools.input:
B=<scratch>; R=$B/s1/R5; mkdir -p $R/work $R/state; cd $R/work
cat > q.tuft <<'EOF'
@h := find text "#[test]" in "crates/writfold-app/src/trial/" at "c568505742d00859cad758924c98d8d0a6e98648" limit 200;
@e := retain @h around lines 0;
@v := project @e [path, line, excerpt(max_chars: 300)];
emit @v budget_tokens 8000;
EOF
$B/bin/writfold tuft run q.tuft --repo $R/repo --state $R/state | tee out.txt
